import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import * as Diff from 'diff';
import './DiffChecker.css';

const DiffChecker = () => {
  const [originalText, setOriginalText] = useState('');
  const [changedText, setChangedText] = useState('');
  const [showDiff, setShowDiff] = useState(false);
  const [diffResults, setDiffResults] = useState([]);

  const findDifference = () => {
    // Split texts into lines
    const originalLines = originalText.split('\n');
    const changedLines = changedText.split('\n');

    // Get line-level diff
    const lineDiff = Diff.diffLines(originalText, changedText);

    // Build aligned diff results
    const alignedResults = [];
    let originalLineNum = 0;
    let changedLineNum = 0;

    lineDiff.forEach((part) => {
      const lines = part.value.split('\n');
      // Remove empty last element if exists
      if (lines[lines.length - 1] === '') {
        lines.pop();
      }

      if (!part.added && !part.removed) {
        // Unchanged lines - show on both sides
        lines.forEach((line) => {
          alignedResults.push({
            originalLine: {
              text: line,
              lineNum: ++originalLineNum,
              type: 'unchanged',
              parts: null
            },
            changedLine: {
              text: line,
              lineNum: ++changedLineNum,
              type: 'unchanged',
              parts: null
            }
          });
        });
      } else if (part.removed && !part.added) {
        // Lines only in original (deleted)
        lines.forEach((line) => {
          alignedResults.push({
            originalLine: {
              text: line,
              lineNum: ++originalLineNum,
              type: 'removed',
              parts: [{ value: line, removed: true }]
            },
            changedLine: null
          });
        });
      } else if (part.added && !part.removed) {
        // Lines only in changed (added)
        lines.forEach((line) => {
          alignedResults.push({
            originalLine: null,
            changedLine: {
              text: line,
              lineNum: ++changedLineNum,
              type: 'added',
              parts: [{ value: line, added: true }]
            }
          });
        });
      }
    });

    // Now process the aligned results to find modified lines
    // Look for consecutive removed/added pairs and merge them as modifications
    const processedResults = [];
    let i = 0;

    while (i < alignedResults.length) {
      const current = alignedResults[i];
      const next = alignedResults[i + 1];

      // Check if current is removed and next is added (potential modification)
      if (current.originalLine && !current.changedLine && 
          next && !next.originalLine && next.changedLine) {

        // This is a modification - do word-level diff
        const originalText = current.originalLine.text;
        const changedText = next.changedLine.text;

        // Use word-level diff for better readability
        const wordDiff = Diff.diffWords(originalText, changedText);

        // Separate parts for original and changed
        const originalParts = wordDiff.filter(p => !p.added);
        const changedParts = wordDiff.filter(p => !p.removed);

        processedResults.push({
          originalLine: {
            text: originalText,
            lineNum: current.originalLine.lineNum,
            type: 'modified',
            parts: originalParts
          },
          changedLine: {
            text: changedText,
            lineNum: next.changedLine.lineNum,
            type: 'modified',
            parts: changedParts
          }
        });

        i += 2; // Skip both lines
      } else {
        processedResults.push(current);
        i++;
      }
    }

    setDiffResults(processedResults);
    setShowDiff(true);
  };

  const clearAll = () => {
    setOriginalText('');
    setChangedText('');
    setShowDiff(false);
    setDiffResults([]);
  };

  const renderLineParts = (parts) => {
    if (!parts || parts.length === 0) {
      return '\u00A0';
    }

    return parts.map((part, partIndex) => {
      if (part.added) {
        return (
          <span key={partIndex} className="word-added">
            {part.value}
          </span>
        );
      } else if (part.removed) {
        return (
          <span key={partIndex} className="word-removed">
            {part.value}
          </span>
        );
      } else {
        return <span key={partIndex}>{part.value}</span>;
      }
    });
  };

  const renderDiffRow = (row, index) => {
    return (
      <div key={index} className="diff-row">
        {/* Original side */}
        <div className={`diff-cell ${row.originalLine ? row.originalLine.type : 'empty'}`}>
          {row.originalLine ? (
            <>
              <span className="line-number">{row.originalLine.lineNum}</span>
              <span className="line-content">
                {row.originalLine.parts ? 
                  renderLineParts(row.originalLine.parts) : 
                  (row.originalLine.text || '\u00A0')
                }
              </span>
            </>
          ) : (
            <>
              <span className="line-number empty-line-num"></span>
              <span className="line-content empty-content"></span>
            </>
          )}
        </div>

        {/* Changed side */}
        <div className={`diff-cell ${row.changedLine ? row.changedLine.type : 'empty'}`}>
          {row.changedLine ? (
            <>
              <span className="line-number">{row.changedLine.lineNum}</span>
              <span className="line-content">
                {row.changedLine.parts ? 
                  renderLineParts(row.changedLine.parts) : 
                  (row.changedLine.text || '\u00A0')
                }
              </span>
            </>
          ) : (
            <>
              <span className="line-number empty-line-num"></span>
              <span className="line-content empty-content"></span>
            </>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="diff-checker-page">
      <div className="diff-header">
        <Link to="/" className="back-button">← Back to Home</Link>
        <h1>Diff Checker</h1>
        <p>Compare and find differences between two texts</p>
      </div>

      <div className="diff-container">
        {!showDiff ? (
          <div className="input-section">
            <div className="text-input-container">
              <div className="text-input-box">
                <h3>Original Text</h3>
                <textarea
                  value={originalText}
                  onChange={(e) => setOriginalText(e.target.value)}
                  placeholder="Paste your original text here..."
                  className="text-area"
                />
              </div>
              <div className="text-input-box">
                <h3>Changed Text</h3>
                <textarea
                  value={changedText}
                  onChange={(e) => setChangedText(e.target.value)}
                  placeholder="Paste your changed text here..."
                  className="text-area"
                />
              </div>
            </div>
            <div className="button-group">
              <button onClick={findDifference} className="find-diff-button">
                Find Difference
              </button>
              <button onClick={clearAll} className="clear-button">
                Clear All
              </button>
            </div>
          </div>
        ) : (
          <div className="results-section">
            <div className="results-header">
              <h2>Comparison Results</h2>
              <button onClick={() => setShowDiff(false)} className="edit-button">
                ← Edit Texts
              </button>
            </div>
            <div className="legend">
              <span className="legend-item">
                <span className="legend-color removed-color"></span>
                Deletions
              </span>
              <span className="legend-item">
                <span className="legend-color added-color"></span>
                Additions
              </span>
              <span className="legend-item">
                <span className="legend-color modified-color"></span>
                Modifications
              </span>
            </div>
            <div className="diff-results-aligned">
              <div className="diff-headers">
                <div className="diff-header-cell">
                  <h3>Original Text</h3>
                </div>
                <div className="diff-header-cell">
                  <h3>Changed Text</h3>
                </div>
              </div>
              <div className="diff-content-aligned">
                {diffResults.map((row, index) => renderDiffRow(row, index))}
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DiffChecker;
